/**
 * Auth Routes — Registration, login, admin 2FA, token refresh, logout.
 * Generated by BackendForge
 */

const express = require('express');
const router = express.Router();
const authController = require('../controllers/auth.controller');
const { authenticate } = require('../middleware/auth.middleware');
const { authLimiter } = require('../middleware/rate-limiter.middleware');
const { validate, schemas } = require('../middleware/validator.middleware');

// ─── Public Routes ──────────────────────────────────────────

// Customer registration
router.post('/register',
  authLimiter,
  validate(schemas.register),
  authController.register
);

// Customer/Admin login (step 1)
router.post('/login',
  authLimiter,
  validate(schemas.login),
  authController.login
);

// Admin login (step 1 — sends OTP)
router.post('/admin/login',
  authLimiter,
  validate(schemas.adminLogin),
  authController.adminLogin
);

// Admin OTP verification (step 2)
router.post('/admin/verify-otp',
  authLimiter,
  validate(schemas.verifyOtp),
  authController.verifyAdminOTP
);

// Token refresh
router.post('/refresh',
  authController.refreshToken
);

// Password reset request
router.post('/forgot-password',
  authLimiter,
  authController.forgotPassword
);

// Password reset with token
router.post('/reset-password',
  authController.resetPassword
);

// ─── Protected Routes ───────────────────────────────────────

// Logout
router.post('/logout',
  authenticate,
  authController.logout
);

// Get current user
router.get('/me',
  authenticate,
  authController.getCurrentUser
);

module.exports = router;
